class Base
{
void a()
{
cout << "a ";
}
void c()
{
cout << "c ";
}
void e()
{
cout << "e ";
}
// 2. Для шагов, требующих особенной реализации, определите
// "замещающие" методы.
virtual void ph1() = 0;
virtual void ph2() = 0;
public:
// 1. Стандартизуйте основу алгоритма в шаблонном методе
// базового класса
void execute()
{
a();
ph1();
c();
ph2();
e();
}
};
class One: public Base
{
// 3. Производные классы реализуют "замещающие" методы.
